catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    // Converte a data digitada, no formato do usuário, em um número comparável
    function paraData(valor) {
        var fmt = g_user_date_format;                       // ex.: "dd/MM/yyyy"
        var dia = parseInt(valor.substr(fmt.indexOf('dd'), 2), 10);
        var mes = parseInt(valor.substr(fmt.indexOf('MM'), 2), 10);
        var posAno = fmt.indexOf('yyyy');
        var ano = posAno > -1
            ? parseInt(valor.substr(posAno, 4), 10)
            : 2000 + parseInt(valor.substr(fmt.indexOf('yy'), 2), 10);
        return Date.UTC(ano, mes - 1, dia);
    }

    var inicio = g_form.getValue('data_inicio');
    var fim = g_form.getValue('data_fim');
    var vender = g_form.getValue('vender_dias');
    g_form.hideFieldMsg('data_fim');
    g_form.hideFieldMsg('vender_dias');
    if (!inicio || !fim) return;

    var dias = Math.round((paraData(fim) - paraData(inicio)) / (1000*60*60*24)) + 1;

    if (isNaN(dias)) {
        g_form.clearValue('dias_solicitados');
        g_form.showFieldMsg('data_fim',
          'Não foi possível calcular o período. Confira as datas.', 'error');
        return;
    }
    if (dias <= 0) {
        g_form.clearValue('data_fim');
        g_form.clearValue('dias_solicitados');
        g_form.showFieldMsg('data_fim',
          'A data final deve ser após a inicial.', 'error');
        return;
    }
    g_form.setValue('dias_solicitados', dias);

    var vendeu = String(vender).toLowerCase();
    if (vendeu === 'true' || vendeu === 'yes') {
        var msg = '';
        if (dias < 20) {
            msg = 'Para vender 10 dias, o período solicitado deve ter 20 dias.';
        } else if (dias > 20) {
            msg = 'Ao vender 10 dias, o período de descanso pode ter no máximo 20 dias.';
        }
        if (msg) {
            g_form.showFieldMsg('vender_dias', msg, 'error');
        }
    }
}
